"""Full training, evaluation, and reporting pipeline for search ranking and position debiasing."""

from __future__ import annotations

import argparse
import json
import platform
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import sklearn

from . import config, data, metrics, models

CAVEATS = [
    "Impressions and clicks are generated by a simulated cascade position-examination model.",
    "Real search users display multi-click sessions, query reformulation, and satisfaction abandonments.",
    "Position bias eta is assumed known; production deployments estimate propensities via randomization or dual learning.",
    "Relevance grades reflect static document utility rather than dynamic personalized intent.",
]


def _versions() -> dict[str, str]:
    return {
        "python": platform.python_version(),
        "numpy": np.__version__,
        "sklearn": sklearn.__version__,
    }


def run_pipeline(
    results_dir: Path | None = None,
    fast_mode: bool = False,
) -> tuple[dict, dict]:
    """Execute the full ranking evaluation pipeline."""
    out_dir = results_dir or config.RESULTS_DIR
    out_dir.mkdir(parents=True, exist_ok=True)

    n_train = config.FAST_TRAIN_QUERIES if fast_mode else config.TRAIN_QUERIES
    n_test = config.FAST_TEST_QUERIES if fast_mode else config.TEST_QUERIES

    train_ds = data.generate_ranking_data(n_train, seed=config.SEED)
    test_ds = data.generate_ranking_data(n_test, seed=config.SEED + 100)

    # Checksum validation outside fast mode
    if not fast_mode and config.CHECKSUM_FILE.exists():
        expected_sha = config.CHECKSUM_FILE.read_text(encoding="utf-8").strip().split()[0]
        if train_ds.sha256 != expected_sha:
            raise RuntimeError(
                f"Data fingerprint {train_ds.sha256} does not match expected checksum {expected_sha}."
            )

    # Instantiate and fit rankers
    prod_ranker = models.ProductionRanker().fit(train_ds)
    naive_ranker = models.NaiveClickRanker(seed=config.SEED).fit(train_ds)
    ips_ranker = models.IPSDebiasedRanker(seed=config.SEED).fit(train_ds)

    # Evaluate all models on test set
    prod_eval = metrics.evaluate_ranker(prod_ranker, test_ds)
    naive_eval = metrics.evaluate_ranker(naive_ranker, test_ds)
    ips_eval = metrics.evaluate_ranker(ips_ranker, test_ds)

    # Evaluate decision gate for headline model (IPS debiased)
    gate_result = metrics.evaluate_decision_gate(
        headline_eval=ips_eval,
        baseline_eval=prod_eval,
        seed=config.SEED,
    )

    # Measure traps
    traps = metrics.compute_traps(
        dataset=test_ds,
        prod_eval=prod_eval,
        naive_eval=naive_eval,
        ips_eval=ips_eval,
    )

    # Clean query-level arrays from summary metrics payload
    models_summary = {
        "prod_baseline": {
            "overall": prod_eval["overall"],
            "segments": prod_eval["segments"],
        },
        "naive_click": {
            "overall": naive_eval["overall"],
            "segments": naive_eval["segments"],
            "lift_vs_prod": {
                "true_ndcg": naive_eval["overall"]["true_ndcg"] - prod_eval["overall"]["true_ndcg"],
                "click_ndcg": naive_eval["overall"]["click_ndcg"]
                - prod_eval["overall"]["click_ndcg"],
                "ips_ndcg": naive_eval["overall"]["ips_ndcg"] - prod_eval["overall"]["ips_ndcg"],
            },
        },
        "ips_debiased": {
            "overall": ips_eval["overall"],
            "segments": ips_eval["segments"],
            "lift_vs_prod": {
                "true_ndcg": ips_eval["overall"]["true_ndcg"] - prod_eval["overall"]["true_ndcg"],
                "click_ndcg": ips_eval["overall"]["click_ndcg"]
                - prod_eval["overall"]["click_ndcg"],
                "ips_ndcg": ips_eval["overall"]["ips_ndcg"] - prod_eval["overall"]["ips_ndcg"],
            },
        },
    }

    # Headline block for metrics.json
    headline_lift = gate_result["true_ndcg_lift"]
    headline_ci = gate_result["true_ndcg_lift_ci_95"]
    headline_block = {
        "model": config.HEADLINE_MODEL,
        "metric": "true_unbiased_ndcg_lift_at_10",
        "value": float(round(headline_lift, 4)),
        "ci_95": [float(round(headline_ci[0], 4)), float(round(headline_ci[1], 4))],
        "ci_method": "paired_query_bootstrap_percentile",
    }

    # Plot comparison across query segments
    plot_path = out_dir / "ranking_comparison.png"
    _plot_ranking(models_summary, plot_path)

    metrics_payload = {
        "project": "19-search-ranking",
        "data_source": "simulated_known_truth",
        "fast_mode": fast_mode,
        "seed": config.SEED,
        "versions": _versions(),
        "data": {
            "train_queries": n_train,
            "test_queries": n_test,
            "candidates_per_query": config.CANDIDATES_PER_QUERY,
            "train_impressions": train_ds.total_impressions,
            "train_clicks": train_ds.total_clicks,
            "test_impressions": test_ds.total_impressions,
            "test_clicks": test_ds.total_clicks,
            "sha256": train_ds.sha256,
        },
        "assumptions": {
            "position_decay_eta": config.POSITION_DECAY_ETA,
            "max_ips_weight": config.MAX_IPS_WEIGHT,
            "min_true_ndcg_lift": config.MIN_TRUE_NDCG_LIFT,
            "min_tail_ndcg_lift": config.MIN_TAIL_NDCG_LIFT,
        },
        "headline": headline_block,
        "gate": gate_result,
        "models": models_summary,
        "traps": traps,
        "caveats": CAVEATS,
    }

    # Error analysis payload
    error_analysis_payload = {
        "project": "19-search-ranking",
        "fast_mode": fast_mode,
        "query_segments": {
            seg: {
                "prod_true_ndcg": round(prod_eval["segments"][seg]["true_ndcg"], 4),
                "naive_true_ndcg": round(naive_eval["segments"][seg]["true_ndcg"], 4),
                "ips_true_ndcg": round(ips_eval["segments"][seg]["true_ndcg"], 4),
                "naive_lift": round(
                    naive_eval["segments"][seg]["true_ndcg"]
                    - prod_eval["segments"][seg]["true_ndcg"],
                    4,
                ),
                "ips_lift": round(
                    ips_eval["segments"][seg]["true_ndcg"]
                    - prod_eval["segments"][seg]["true_ndcg"],
                    4,
                ),
            }
            for seg in config.QUERY_PROBS
        },
        "clicks_by_position": test_ds.clicks_by_position,
        "post_hoc_study": {
            "status": "designed_after_results_does_not_change_verdict",
            "observation": (
                "Tail queries exhibit severe popularity bias distortion under naive rankers "
                "because distractor items that were historically exposed at high ranks accumulate "
                "clicks from casual examinations. IPS weighting eliminates this distractor effect."
            ),
        },
    }

    (out_dir / "metrics.json").write_text(json.dumps(metrics_payload, indent=2), encoding="utf-8")
    (out_dir / "error_analysis.json").write_text(
        json.dumps(error_analysis_payload, indent=2), encoding="utf-8"
    )

    return metrics_payload, error_analysis_payload


def _plot_ranking(models_summary: dict, out_path: Path) -> None:
    """Generate bar chart comparing True NDCG@10 across query segments."""
    _fig, ax = plt.subplots(figsize=(8, 5))
    segments = ["head", "torso", "tail"]
    x = np.arange(len(segments))
    width = 0.25

    model_keys = ["prod_baseline", "naive_click", "ips_debiased"]
    labels = ["Production Baseline", "Naive Click Ranker", "IPS Debiased (Headline)"]
    colors = ["#7f8c8d", "#e74c3c", "#27ae60"]

    for i, (m_key, label, color) in enumerate(zip(model_keys, labels, colors, strict=True)):
        scores = [models_summary[m_key]["segments"][seg]["true_ndcg"] for seg in segments]
        ax.bar(x + (i - 1) * width, scores, width, label=label, color=color)

    ax.set_ylabel("True Unbiased NDCG@10")
    ax.set_title("Search Ranking: Production vs Naive Click vs IPS Debiased")
    ax.set_xticks(x)
    ax.set_xticklabels([s.capitalize() + " Queries" for s in segments])
    ax.set_ylim(0.5, 1.0)
    ax.legend(frameon=True)
    ax.grid(axis="y", linestyle="--", alpha=0.5)

    plt.tight_layout()
    plt.savefig(out_path, dpi=150)
    plt.close()


def main() -> None:
    parser = argparse.ArgumentParser(description="Run search ranking and debiasing pipeline.")
    parser.add_argument(
        "--fast", action="store_true", help="Run quick smoke test with reduced dataset."
    )
    parser.add_argument(
        "--write-checksum", action="store_true", help="Write dataset SHA-256 to CHECKSUMS.txt."
    )
    args = parser.parse_args()

    metrics_res, _ = run_pipeline(fast_mode=args.fast)

    if args.write_checksum:
        sha = metrics_res["data"]["sha256"]
        config.CHECKSUM_FILE.parent.mkdir(parents=True, exist_ok=True)
        config.CHECKSUM_FILE.write_text(f"{sha}  simulated_queries\n", encoding="utf-8")
        print(f"Wrote checksum {sha} to {config.CHECKSUM_FILE}")

    print(f"Pipeline complete. Gate passed: {metrics_res['gate']['passed']}")


if __name__ == "__main__":
    main()
